## 6. Advanced Features

### A. Multi-Turn Conversations (Session Management)

Keep Claude in the same conversation across multiple interactions:

**TypeScript:**
```typescript
import { query } from "@anthropic-ai/claude-agent-sdk";

// First query
let sessionId: string | undefined;

for await (const message of query({
  prompt: "Read the authentication module",
  options: { allowedTools: ["Read", "Glob"] }
})) {
  if (message.type === 'system' && message.subtype === 'init') {
    sessionId = message.session_id;
    console.log(`Session: ${sessionId}`);
  }
}

// Resume the same session - Claude remembers context
for await (const message of query({
  prompt: "Now find all places that call it",  // "it" = auth module from before
  options: { 
    resume: sessionId,  // Continue same conversation
    allowedTools: ["Grep", "Read"]
  }
})) {
  console.log(message);
}
```

**Python:**
```python
from claude_agent_sdk import query, ClaudeAgentOptions

session_id = None

# First query
async for message in query(
    prompt="Read the authentication module",
    options=ClaudeAgentOptions(allowed_tools=["Read", "Glob"])
):
    if hasattr(message, 'subtype') and message.subtype == 'init':
        session_id = message.data.get('session_id')
        print(f"Session: {session_id}")

# Resume with full context
async for message in query(
    prompt="Now find all places that call it",  # Claude remembers context!
    options=ClaudeAgentOptions(
        resume=session_id,  # Same conversation continues
        allowed_tools=["Grep", "Read"]
    )
):
    print(message)
```

### B. Using ClaudeSDKClient for Continuous Conversations

For interactive applications, use `ClaudeSDKClient` instead of `query()`:

**TypeScript:**
```typescript
import { ClaudeSDKClient } from "@anthropic-ai/claude-agent-sdk";

const client = new ClaudeSDKClient({
  allowedTools: ["Read", "Write", "Bash"],
  permissionMode: "acceptEdits"
});

await client.connect();

// First exchange
await client.query("What's the capital of France?");
for await (const message of client.receive_response()) {
  console.log(message);
}

// Follow-up - Claude remembers previous context
await client.query("What's the population of that city?");
for await (const message of client.receive_response()) {
  console.log(message);
}

// Another follow-up - still in same session
await client.query("What are famous landmarks there?");
for await (const message of client.receive_response()) {
  console.log(message);
}

await client.disconnect();
```

**Python:**
```python
from claude_agent_sdk import ClaudeSDKClient, ClaudeAgentOptions

options = ClaudeAgentOptions(
    allowed_tools=["Read", "Write", "Bash"],
    permission_mode="acceptEdits"
)

async with ClaudeSDKClient(options=options) as client:
    # First exchange
    await client.query("What's the capital of France?")
    async for message in client.receive_response():
        print(message)

    # Follow-up with context
    await client.query("What's the population of that city?")
    async for message in client.receive_response():
        print(message)

    # Another follow-up
    await client.query("What are famous landmarks there?")
    async for message in client.receive_response():
        print(message)
```

### C. Forking Sessions

Create branches from a session to explore different approaches:

**TypeScript:**
```typescript
// Capture initial session
let sessionId: string | undefined;
for await (const message of query({
  prompt: "Design a REST API",
  options: { model: "claude-opus-4-5-20251101" }
})) {
  if (message.type === 'system' && message.subtype === 'init') {
    sessionId = message.session_id;
  }
}

// Fork to try different approach (new session ID)
for await (const message of query({
  prompt: "Now redesign as GraphQL instead",
  options: {
    resume: sessionId,
    forkSession: true  // Creates new branch
  }
})) {
  console.log(message);
}

// Original session unchanged for other branches
for await (const message of query({
  prompt: "Add authentication to REST API",
  options: {
    resume: sessionId,
    forkSession: false  // Continue original
  }
})) {
  console.log(message);
}
```

